  "프로그램을 켤 때마다 Grok 연결을 준비합니다. 꺼 두면 Grok 기능이 동작하지 않습니다.": "プログラムの電源を入れるたびに Grok 接続を準備します。オフにすると Grok 機能は動作しません。",
  "같은 공유기에 연결된 기기(휴대폰·태블릿)에서 위 주소로 접속할 수 있습니다. 접속이 안 되면 Windows 방화벽의 NAIA(Python) 허용과 공유기 AP 격리 설정을 확인하세요.": "同じルーターに接続された機器（携帯電話・タブレット）から上のアドレスで接続できます。アクセスできない場合は、WindowsファイアウォールのNAIA（Python）を許可し、ルーターAPの分離設定を確認してください。",
