  "이미지를 생성할 때 저장 폴더에도 자동 저장합니다.": "画像の生成時に保存フォルダにも自動保存します。",
  "같은 프롬프트로 N회 생성한 뒤 다음 프롬프트로 넘어갑니다(시드는 매번 재랜덤화되어 변주가 생깁니다).\\n\\n자동 생성(자동화 시작) 상태에서만 동작하며, 값은 저장되지 않고 항상 1로 시작합니다.": "同じプロンプトでN回生成した後、次のプロンプトに進みます（シードは毎回再ランダム化され、バリエーションが発生します）。",
  "자동화 종료 조건입니다.\\n\\n무제한 = 수동 정지까지 계속 / 타이머 = 지정한 시간이 지나면 종료 / 횟수 = 지정한 장수를 생성하면 종료.": "自動化終了条件です。\\n\\n無制限=手動停止まで継続/タイマー=指定した時間が経過したら終了/回数=指定した長数を生成すると終了。",
  "각 생성 사이의 대기 시간(초)입니다.\\n\\n무작위 ±50%를 켜면 설정값의 50~150% 범위에서 흔들어 생성 간격 패턴을 깹니다.": "各生成間の待機時間（秒）。",
