  "처리 중...": "処理中...",
  "일괄 다운로드": "一括ダウンロード",
  "무작위 ±50%": "ランダム±50％",
  "딜레이 (초)": "ディレイ(秒)",
  "이미지를 저장하지 않고 Remote Web 히스토리에만 유지합니다.": "画像を保存せずにリモートWeb履歴にのみ保存します。",
  "저장 순서": "保存順序",
  "[1] 1장씩 자동저장+정리": "[1] 1枚ずつ自動保存+整理",
  "Auto Gen을 켜면 저장된 자동화 설정(종료 조건·딜레이 등)으로 자동화가 함께 시작됩니다 — Auto Gen이 트리거입니다.\\n\\n완료(횟수/타이머 도달)·정지 시 자동화와 Auto Gen이 모두 꺼지며 무한 생성되지 않습니다. 다시 돌리려면 Auto Gen을 다시 켜세요.": "Auto Genをオンにすると、保存されたオートメーション設定（終了条件、遅延など）で自動化が開始されます。Auto Genはトリガです。\\ n \\ n完了（カウント/タイマー到達）元に戻すには、Auto Genをもう一度オンにします。",
