  "가상": "仮想",
  "원본 C{0} 이(가) 꺼져 있어 **아무것도 물려받지 못합니다**.\\n원본의 ✔ 를 다시 켜거나 연결을 바꾸세요.": "元のC{0}がオフになっています**何も受け入れられません**。\\n元の✔を再びオンにするか、接続を変更してください",
