  "Connect 를 쓰는 동안에는 POS 가 CUSTOM 으로 고정됩니다 (칸마다 직접 앉히는 기능입니다)": "Connectを書いている間は、POSはCUSTOMに固定されます（スペースごとに直接座る機能です）",
  "Rnd Res 중에는 POS 가 AUTO 로 고정됩니다 (해상도가 매 생성마다 바뀌어 좌표를 앉힐 캔버스가 없습니다)": "Rnd Res中は、POSがAUTOに固定されます（解像度が生成ごとに変わり、座標を座らせるキャンバスはありません）",
  "C{0} 의 캐릭터를 물려받는 중입니다.\\n아래 두 칸은 '추가할' 칸입니다.\\n\\n물려받는 범위는 C{1} 의 &connect: … &end 구간이 정합니다.\\n\\n-태그 를 적으면 그 태그를 빼고 물려받습니다.": "C{0}のキャラクターを継承しています。\n下の2欄には追加する内容を入力します。\n\n継承範囲は、C{1}の &connect: … &end 区間で決まります。\n\n-タグ と入力すると、そのタグを除外して継承します。",
  "Generate 버튼을 누를 때 캐릭터 와일드카드 재굴림": "「生成」ボタンを押したときのキャラクターのワイルドカードのリロール",
  "data-naia-guide=\"Connect 를 쓰는 동안에는 POS 가 CUSTOM 으로 고정됩니다.\\n같은 캐릭터를 칸마다 직접 앉히는 기능이라 AUTO/RAND 가 자리를 정하면 안 됩니다.\"": "data-naia-guide=\"Connect を書いている間は POS が CUSTOM に固定されます。",
  "캐릭터 프롬프트를 복사했습니다.": "キャラクタープロンプトをコピーしました。",
  "앞선 슬롯의 캐릭터를 그대로 물려받습니다.\\n와일드카드도 같은 값이 옵니다.\\n\\n연결하면 원본에 &connect: … &end 가 자동으로 붙습니다. &end 를 앞으로 당기면 그만큼만 물려줍니다.": "前のスロットの文字はそのまま継承されます。\\nワイルド カードも同じ値を持ちます。\\n\\n接続すると、&connect: … が元のスロットに接続されます。 &endが自動的に追加されます。 &endを前に引くと、その分だけ転送されます。",
  "캐릭터 프롬프트를 활성화 합니다 (NAID4 이상)": "文字プロンプトを有効にする (NAID4 以降)",
