  "기간 컷오프 — 태그 아카이브를 날짜 구간으로 제한합니다. 선택한 [시작–끝] 버킷만 검색해 속도를 높이고 모델 학습 컷오프에 맞춥니다.\\n\\n핸들을 드래그해 시작·끝 시점을 정하면 그 구간의 parquet만 스캔합니다(구간이 좁을수록 빠름).\\n\\n핸들에 마우스를 올리면 해당 YYYY/MM, 아래에 선택된 parquet 수가 표시됩니다. 위치는 자동 저장됩니다.": "期間カットオフ - タグアーカイブを日付区間に制限します。選択した[開始 - 終了]バケットだけを検索して速度を上げてモデル学習カットオフに合わせます。場所は自動的に保存されます。",
